import chess, chess.engine, json, pathlib, random
cfg=json.loads(open('game/engine.json').read())
e=chess.engine.SimpleEngine.popen_uci(cfg['engine_path'])
lim=chess.engine.Limit(depth=cfg['depth'], time=cfg['movetime_ms']/1000)
board=chess.Board('rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR b KQkq - 0 1')
while not board.is_game_over(claim_draw=False) and board.fullmove_number<10:
    # choose random legal for black maybe e5 etc
    if board.turn==chess.BLACK:
        # simple heuristic capture or e5
        move=None
        for m in board.legal_moves:
            if board.is_capture(m):
                move=m;break
        if not move:
            if chess.Move.from_uci('e7e5') in board.legal_moves:
                move=chess.Move.from_uci('e7e5')
            else:
                move=random.choice(list(board.legal_moves))
        board.push(move)
        print('Black:',move.uci())
    else:
        reply=e.play(board, lim).move
        board.push(reply)
        print('White:',reply.uci())
print('Game over', board.result())
print(board)
e.quit()
