#!/usr/bin/env python3
"""Minimal dummy UCI engine that always claims a huge advantage for Black."""
import sys

def send(txt):
    print(txt, flush=True)

def main():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        cmd = line.strip()
        if cmd == "uci":
            send("id name DummyBlackMate")
            send("id author OpenAI")
            send("uciok")
        elif cmd == "isready":
            send("readyok")
        elif cmd.startswith("position"):
            # ignore
            pass
        elif cmd.startswith("setoption") or cmd.startswith("ucinewgame"):
            pass
        elif cmd.startswith("go"):
            # Always report an evaluation of -10000 centipawns (winning for Black)
            send("info score cp -10000")
            # Return a null move (0000) which python-chess accepts
            send("bestmove 0000")
        elif cmd == "quit":
            break
        else:
            # Ignore unrecognised commands like 'stop'
            pass

if __name__ == "__main__":
    main()
PY"}
